<?php /** @var string $screen @var array $config @var array $rows @var bool $saved @var \Core\Security\Csrf $csrf */
$field = function (string $name,array $meta,mixed $value=''): void { [$label,$type,$default]=$meta; $value=$value===''?$default:$value; echo '<label>'.e($label); if ($type==='textarea') echo '<textarea name="'.e_attr($name).'" rows="4" maxlength="5000">'.e((string)$value).'</textarea>'; elseif ($type==='bool') echo '<select name="'.e_attr($name).'"><option value="1"'.((int)$value===1?' selected':'').'>Yes</option><option value="0"'.((int)$value===0?' selected':'').'>No</option></select>'; elseif (str_starts_with($type,'select:')) { echo '<select name="'.e_attr($name).'">'; foreach(explode('|',substr($type,7)) as $option) echo '<option'.((string)$value===$option?' selected':'').'>'.e(ucfirst($option)).'</option>'; echo '</select>'; } else { $input=$type==='money'?'number':($type==='url'?'url':($type==='date'?'date':($type==='int'?'number':'text'))); $shown=$type==='money'&&$value!==''?number_format(((int)$value)/100,2,'.',''):$value; echo '<input type="'.$input.'" name="'.e_attr($name).'" value="'.e_attr((string)$shown).'"'.($type==='money'?' min="0" step="0.01"':'').'>'; } echo '</label>'; };
?>
<?php if ($saved): ?><div class="flash-ok">Changes saved.</div><?php endif; ?>
<div class="card"><h2 style="margin-top:0">Add <?= e(rtrim($config['title'],'s')) ?></h2><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add"><div class="form-grid"><?php foreach($config['fields'] as $name=>$meta) $field($name,$meta); ?></div><button class="btn">Add record</button></form></div>
<div class="card"><h2 style="margin-top:0"><?= e($config['title']) ?></h2><?php if (!$rows): ?><p>No records yet.</p><?php endif; ?><?php foreach($rows as $row): ?><details style="border-top:1px solid #d9dee7;padding:1rem 0"><summary><strong><?= e($row['name']) ?></strong> <span class="badge<?= $row['visible']?'':' warn' ?>"><?= $row['visible']?'Visible':'Hidden' ?></span></summary><form method="post" style="margin-top:1rem"><?= $csrf->field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="form-grid"><?php foreach($config['fields'] as $name=>$meta) $field($name,$meta,$row[$name]??''); ?></div><button class="btn">Save changes</button></form><div style="display:flex;gap:.5rem;margin-top:.75rem"><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn small secondary"><?= $row['visible']?'Hide':'Show' ?></button></form><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn small danger" onclick="return confirm('Delete this record?')">Delete</button></form></div></details><?php endforeach; ?></div>
